@Test
    public void shouldAcceptIfSingleZKAddressWithPath() {
        String add = "zk://192.168.0.1:2182/mesos";
        List<ZKAddress> zk = new ZKAddressParser().validateZkUrl(add);
        assertZKEquals(zk.get(0), "", "", "192.168.0.1", "2182", "mesos");
    }

